:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #111111;
  --ink-soft: #4a4a4a;
  --muted: #8a8a8a;
  --line: #ececea;
  --accent: #ff5a3c;
  --accent-ink: #ffffff;
  --sale: #c4392c;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.06);
  --maxw: 1240px;
  --space: 24px;
  --font: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --serif: "Playfair Display", "Iowan Old Style", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

button {
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--ink);
  color: #fff;
  padding: 8px 14px;
  border-radius: 8px;
  z-index: 1000;
  transition: top 0.2s ease;
}
.skip-link:focus { top: 12px; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--space);
}

/* ============ TOP BAR ============ */
.announcement {
  background: var(--ink);
  color: #fff;
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-align: center;
  padding: 10px var(--space);
}

/* ============ HEADER ============ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(180%) blur(10px);
  -webkit-backdrop-filter: saturate(180%) blur(10px);
  border-bottom: 1px solid var(--line);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}

.brand {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.6rem;
  letter-spacing: 0.02em;
}

.brand-mark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.brand-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: var(--accent);
  display: inline-block;
}

.primary-nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 28px;
  justify-content: center;
}

.primary-nav a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--ink-soft);
  position: relative;
  padding: 6px 0;
  transition: color 0.15s ease;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a[aria-current="page"] { color: var(--ink); }
.primary-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 2px;
  background: var(--ink);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.icon-btn {
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  position: relative;
  color: var(--ink);
  transition: background 0.15s ease;
}
.icon-btn:hover { background: var(--line); }

.icon-btn svg { width: 20px; height: 20px; stroke-width: 1.6; }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.68rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.menu-toggle { display: none; }

/* ============ HERO ============ */
.hero {
  padding: 48px 0 64px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 56px;
  align-items: center;
}
.hero-eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 18px;
}
.hero-title {
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(2.4rem, 5vw, 4.2rem);
  line-height: 1.05;
  letter-spacing: -0.01em;
  margin: 0 0 22px;
}
.hero-title em {
  font-style: italic;
  color: var(--accent);
}
.hero-lede {
  font-size: 1.08rem;
  color: var(--ink-soft);
  max-width: 46ch;
  margin: 0 0 32px;
}
.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 26px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  transition: transform 0.1s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink);
  color: #fff;
}
.btn-primary:hover { background: #2a2a2a; box-shadow: var(--shadow-md); }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--ink);
}
.btn-ghost:hover { background: var(--ink); color: #fff; }
.btn-block { width: 100%; }

.hero-media {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #efe9e0 0%, #d9d1c4 100%);
  box-shadow: var(--shadow-md);
}
.hero-media img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.hero-badge {
  position: absolute;
  bottom: 22px; left: 22px;
  background: rgba(255,255,255,0.94);
  backdrop-filter: blur(6px);
  border-radius: 14px;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow-sm);
}
.hero-badge .num {
  font-family: var(--serif);
  font-size: 1.6rem;
  font-weight: 700;
}
.hero-badge .lbl {
  font-size: 0.78rem;
  color: var(--ink-soft);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ============ MARQUEE / TRUST BAR ============ */
.trust-bar {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  padding: 22px 0;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.92rem;
  color: var(--ink-soft);
}
.trust-item svg { width: 22px; height: 22px; flex-shrink: 0; }
.trust-item strong { color: var(--ink); display: block; font-size: 0.95rem; }

/* ============ SECTION HEADERS ============ */
.section { padding: 80px 0; }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-eyebrow {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 0 0 10px;
}
.section-title {
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(1.8rem, 3.2vw, 2.6rem);
  line-height: 1.1;
  margin: 0;
  letter-spacing: -0.01em;
}
.section-link {
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}
.section-link:hover { color: var(--accent); }

/* ============ CATEGORY PILLS / FILTER ============ */
.tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.tab {
  padding: 8px 16px;
  border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--line);
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--ink-soft);
  transition: all 0.15s ease;
}
.tab:hover { border-color: var(--ink); color: var(--ink); }
.tab[aria-pressed="true"] {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff;
}

/* ============ PRODUCT GRID ============ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
}

.product-card {
  display: flex;
  flex-direction: column;
  background: transparent;
  position: relative;
}

.product-media {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius);
  overflow: hidden;
  background: #efece6;
  margin-bottom: 14px;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}
.product-card:hover .product-media img {
  transform: scale(1.04);
}

.tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #fff;
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 5px 10px;
  border-radius: 999px;
}
.tag.sale { background: var(--sale); color: #fff; }
.tag.new { background: var(--ink); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px; height: 36px;
  background: rgba(255,255,255,0.92);
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, color 0.15s ease;
}
.wishlist-btn:hover { background: #fff; color: var(--accent); }
.wishlist-btn svg { width: 18px; height: 18px; }
.wishlist-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
}
.wishlist-btn[aria-pressed="true"] svg { fill: currentColor; }

.quick-add {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: #fff;
  border-radius: 999px;
  padding: 10px;
  font-size: 0.86rem;
  font-weight: 600;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.product-card:hover .quick-add,
.product-card:focus-within .quick-add {
  opacity: 1;
  transform: translateY(0);
}

.product-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.product-cat {
  font-size: 0.76rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 4px;
}
.price-current { font-weight: 700; }
.price-old {
  color: var(--muted);
  text-decoration: line-through;
  font-size: 0.88rem;
}
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.82rem;
  color: var(--ink-soft);
  margin-top: 2px;
}
.product-rating svg { width: 14px; height: 14px; color: #f5b400; }

/* ============ DEALS / BANNER ============ */
.deals-band {
  background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.deals-band .eyebrow { color: #ff8b75; }
.deals-band h2 {
  font-family: var(--serif);
  font-size: clamp(2rem, 3.6vw, 3rem);
  margin: 0 0 16px;
  line-height: 1.05;
}
.deals-band p {
  color: rgba(255,255,255,0.72);
  margin: 0 0 24px;
  max-width: 50ch;
}
.deals-band .btn-primary {
  background: var(--accent);
}
.deals-band .btn-primary:hover { background: #ff7359; }

.countdown {
  display: flex;
  gap: 12px;
  margin-bottom: 28px;
}
.cd-cell {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 14px 18px;
  text-align: center;
  min-width: 72px;
}
.cd-num {
  font-family: var(--serif);
  font-size: 1.8rem;
  font-weight: 700;
  display: block;
  font-variant-numeric: tabular-nums;
}
.cd-lbl {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255,255,255,0.6);
}

.deals-side {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.deal-mini {
  background: rgba(255,255,255,0.06);
  border-radius: 14px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  overflow: hidden;
}
.deal-mini .pct {
  font-family: var(--serif);
  font-size: 2.4rem;
  font-weight: 700;
  line-height: 1;
}
.deal-mini .label {
  font-size: 0.92rem;
  color: rgba(255,255,255,0.85);
}
.deal-mini .arrow {
  margin-top: auto;
  align-self: flex-end;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.12);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============ EDITORIAL ============ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.editorial-grid > article:first-child {
  grid-row: span 2;
}

.editorial-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.editorial-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.editorial-media {
  aspect-ratio: 16/10;
  overflow: hidden;
  background: #ddd;
}
.editorial-media img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.6s ease; }
.editorial-card:hover .editorial-media img { transform: scale(1.04); }
.editorial-card.featured .editorial-media { aspect-ratio: 4/5; }
.editorial-body {
  padding: 22px 24px 26px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.editorial-tag {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  font-weight: 600;
}
.editorial-title {
  font-family: var(--serif);
  font-size: 1.35rem;
  line-height: 1.2;
  margin: 0;
}
.editorial-card.featured .editorial-title {
  font-size: 1.8rem;
}
.editorial-excerpt {
  color: var(--ink-soft);
  font-size: 0.95rem;
  margin: 0;
}
.editorial-meta {
  margin-top: auto;
  padding-top: 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.82rem;
  color: var(--muted);
}
.avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg, #ddd, #aaa);
  display: inline-block;
}

/* ============ NEWSLETTER ============ */
.newsletter {
  background: linear-gradient(135deg, #efe9e0 0%, #f6f1e8 100%);
  border-radius: var(--radius-lg);
  padding: 60px 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  margin: 0 0 12px;
  line-height: 1.1;
}
.newsletter p {
  color: var(--ink-soft);
  margin: 0;
}
.newsletter form {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.newsletter input[type="email"] {
  flex: 1;
  min-width: 220px;
  padding: 14px 18px;
  border-radius: 999px;
  border: 1px solid rgba(0,0,0,0.12);
  background: #fff;
  font: inherit;
  color: var(--ink);
}
.newsletter input[type="email"]:focus {
  outline: none;
  border-color: var(--ink);
}
.form-message {
  width: 100%;
  margin-top: 8px;
  font-size: 0.9rem;
  color: var(--ink-soft);
  min-height: 1.2em;
}
.form-message.success { color: #1f7a3a; }

/* ============ FOOTER ============ */
.site-footer {
  background: var(--ink);
  color: #d9d9d9;
  padding: 72px 0 28px;
  margin-top: 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-brand {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.6rem;
  color: #fff;
  margin-bottom: 16px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.footer-tag { max-width: 36ch; color: rgba(255,255,255,0.7); }
.footer-col h3 {
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: #fff;
  margin: 0 0 18px;
}
.footer-col ul {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  gap: 12px;
}
.footer-col a {
  color: rgba(255,255,255,0.72);
  font-size: 0.92rem;
  transition: color 0.15s ease;
}
.footer-col a:hover { color: #fff; }

.socials {
  display: flex;
  gap: 8px;
  margin-top: 18px;
}
.socials a {
  width: 38px; height: 38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  transition: background 0.15s ease;
}
.socials a:hover { background: var(--accent); }
.socials svg { width: 16px; height: 16px; }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  font-size: 0.84rem;
  color: rgba(255,255,255,0.55);
  flex-wrap: wrap;
  gap: 12px;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid > article:first-child { grid-row: auto; grid-column: span 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .header-inner { grid-template-columns: auto 1fr auto; }
  .menu-toggle {
    display: inline-flex;
  }
  .primary-nav {
    position: fixed;
    inset: 0 0 0 auto;
    width: min(80vw, 320px);
    background: #fff;
    box-shadow: -10px 0 30px rgba(0,0,0,0.12);
    transform: translateX(100%);
    transition: transform 0.25s ease;
    padding: 80px 28px 28px;
    z-index: 60;
  }
  .primary-nav[data-open="true"] { transform: translateX(0); }
  .primary-nav ul { flex-direction: column; align-items: flex-start; gap: 18px; }
  .nav-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease;
    z-index: 55;
  }
  .nav-backdrop[data-open="true"] { opacity: 1; pointer-events: auto; }

  .hero { padding: 28px 0 40px; }
  .hero-grid { grid-template-columns: 1fr; gap: 32px; }
  .trust-grid { grid-template-columns: 1fr 1fr; }
  .section { padding: 56px 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 18px; }
  .deals-band { grid-template-columns: 1fr; padding: 36px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-grid > article:first-child { grid-column: auto; }
  .newsletter { grid-template-columns: 1fr; padding: 36px; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
