/* ---------- Deals section with countdown ---------- */
const useCountdown = (target) => {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const hrs = Math.floor((diff / 3600000) % 24);
  const m = Math.floor((diff / 60000) % 60);
  const s = Math.floor((diff / 1000) % 60);
  return { d, h: hrs, m, s };
};

const pad = (n) => String(n).padStart(2, "0");

const DealsSection = () => {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 38 + 24 * 1000, []);
  const t = useCountdown(target);
  const cells = [
    { num: pad(t.d), lbl: "Days" },
    { num: pad(t.h), lbl: "Hours" },
    { num: pad(t.m), lbl: "Minutes" },
    { num: pad(t.s), lbl: "Seconds" },
  ];
  return h("section", { className: "section", id: "deals", "aria-labelledby": "deals-title" },
    h("div", { className: "container" },
      h("div", { className: "deals-band" },
        h("div", null,
          h("p", { className: "section-eyebrow eyebrow" }, "Limited time"),
          h("h2", { id: "deals-title" }, "Spring Sale — up to 40% off"),
          h("p", null, "Hand-picked seasonal favourites at our best prices. Once they're gone, that's it."),
          h("div", { className: "countdown", role: "timer", "aria-label": "Sale ends in" },
            ...cells.map((c) =>
              h("div", { key: c.lbl, className: "cd-cell" },
                h("span", { className: "cd-num", "aria-hidden": "true" }, c.num),
                h("span", { className: "sr-only" }, `${parseInt(c.num,10)} ${c.lbl.toLowerCase()}`),
                h("span", { className: "cd-lbl", "aria-hidden": "true" }, c.lbl)
              )
            )
          ),
          h("a", { href: "#sale", className: "btn btn-primary" },
            "Shop the sale ", h(Icon, { name: "arrow", width: 16, height: 16 })
          )
        ),
        h("div", { className: "deals-side", "aria-label": "Featured deal categories" },
          h("a", { href: "#sale-knit", className: "deal-mini" },
            h("span", { className: "pct" }, "30%"),
            h("span", { className: "label" }, "Knitwear & cardigans"),
