/* ---------- Newsletter ---------- */
const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState({ text: "", ok: false });

  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setMsg({ text: "Please enter a valid email address.", ok: false });
      return;
    }
    setMsg({ text: `Thanks — we've added ${email} to the list.`, ok: true });
    setEmail("");
  };

  return h("section", { className: "section", "aria-labelledby": "news-title" },
    h("div", { className: "container" },
      h("div", { className: "newsletter" },
        h("div", null,
          h("p", { className: "section-eyebrow" }, "Stay close"),
          h("h2", { id: "news-title" }, "New drops, in your inbox first."),
          h("p", null, "Join 60,000+ readers for early access, studio notes, and the occasional reader-only discount.")
        ),
        h("form", { onSubmit, noValidate: true, "aria-describedby": "news-msg" },
          h("label", { htmlFor: "news-email", className: "sr-only" }, "Email address"),
          h("input", {
            id: "news-email",
            type: "email",
            placeholder: "you@domain.com",
            value: email,
            onChange: (e) => setEmail(e.target.value),
            required: true,
            "aria-invalid": msg.text && !msg.ok ? "true" : "false",
          }),
          h("button", { type: "submit", className: "btn btn-primary" }, "Subscribe"),
          h("p", {
            id: "news-msg",
            className: `form-message${msg.ok ? " success" : ""}`,
            role: "status",
            "aria-live": "polite",
          }, msg.text)
        )
      )
    )
  );
};

