/* ---------- App root ---------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(() => new Set());

  const addToCart = (id) => setCart((c) => [...c, id]);
  const toggleWish = (id) => setWishlist((w) => {
    const next = new Set(w);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });

  return h(Fragment, null,
    h("a", { href: "#main", className: "skip-link" }, "Skip to main content"),
    h(Announcement),
    h(Header, { cartCount: cart.length, onCartClick: () => {} }),
    h("main", { id: "main" },
      h(Hero),
      h(TrustBar),
      h(FeaturedSection, { wishlist, onWish: toggleWish, onAdd: addToCart }),
      h(DealsSection),
      h(EditorialSection),
      h(Newsletter)
    ),
    h(Footer)
  );
};

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(h(App));
